          width: 100%;
          z-index: 22;
        }

        .setoff-wrapper {
          display: flex;
          width: 100%;
          justify-content: center;
          background-color: #FFFFFF;
          border-bottom: 1px solid #BDBDBD;
        }

        .setoff-content {
          display: flex;
          justify-content: center;
          align-items: center;
          width: 100%;
          max-width: 1200px;
          font-size: 14px;
          line-height: 17px;
          padding: 8px 16px;
        }

        .setoff-text {
          display: inline;
          letter-spacing: -0.5px;
          text-align: left;
          margin-right: 16px;
          color: #333;
        }

        .setoff-disclosure {
          position: relative;
          display: inline-flex;
          align-items: center;
        }

        .disclosure-btn {
          background: none;
          border: none;
          color: #333;
          font-size: 14px;
          font-weight: 400;
          cursor: pointer;
          padding: 0;
          text-decoration: underline;
          white-space: nowrap;
        }

        .disclosure-btn:hover {
          color: #000;
        }

        .disclosure-popup {
          position: absolute;
          top: 100%;
          right: 0;
          margin-top: 12px;
          width: 320px;
          background: #fff;
          border: 1px solid #e5e7eb;
          border-radius: 8px;
          box-shadow: 0 4px 20px rgba(0, 0, 0, 0.15);
          padding: 16px;
          z-index: 100;
          font-size: 13px;
          line-height: 1.5;
          color: #4b5563;
        }

        .disclosure-popup::before {
          content: '';
          position: absolute;
          top: -6px;
          right: 20px;
          width: 12px;
          height: 12px;
          background: #fff;
          border-left: 1px solid #e5e7eb;
          border-top: 1px solid #e5e7eb;
          transform: rotate(45deg);
        }

        .disclosure-popup p {
          margin: 0;
        }

